import type { Bookmark } from '../api';

// Bookmark list showing title, address, and save date, with a first-run
// empty-state guide instead of a blank screen (FR-006, FR-015).
export function BookmarkList({ bookmarks }: { bookmarks: Bookmark[] }) {
  if (bookmarks.length === 0) {
    return (
      <div className="empty">
        <h2>No bookmarks yet</h2>
        <p>
          Paste a web address above and choose <strong>Save bookmark</strong> to
          add your first one.
        </p>
      </div>
    );
  }

  return (
    <ul className="bookmark-list">
      {bookmarks.map((b) => (
        <li key={b.id} className="bookmark">
          <a href={b.url} target="_blank" rel="noreferrer" className="title">
            {b.title}
          </a>
          <span className="url">{b.url}</span>
          <span className="date">
            Saved {new Date(b.createdAt).toLocaleDateString()}
          </span>
          {b.tags.length > 0 && (
            <span className="tags">
              {b.tags.map((t) => (
                <span key={t} className="tag">
                  {t}
                </span>
              ))}
            </span>
          )}
        </li>
      ))}
    </ul>
  );
}

