import type { FastifyInstance } from 'fastify';
import type { DB } from '../db.js';
import { createBookmark, listBookmarks } from '../services/bookmarks.js';

// /api/bookmarks endpoints. US1 scope: create + list (contracts/api.md).
// Search, detail, edit, delete/undo are added in later story phases.
export function registerBookmarkRoutes(app: FastifyInstance, db: DB): void {
  app.get('/api/bookmarks', async (req) => {
    const q = req.query as { sort?: 'created_desc' | 'created_asc' | 'title_asc' };
    return { bookmarks: listBookmarks(db, { sort: q.sort }) };
  });

  app.post('/api/bookmarks', async (req, reply) => {
    const body = (req.body ?? {}) as {
      url?: string;
      title?: string;
      description?: string;
      tags?: string[];
    };
    const bookmark = await createBookmark(db, {
      url: body.url ?? '',
      title: body.title,
      description: body.description,
      tags: body.tags,
    });
    return reply.code(201).send(bookmark);
  });
}

