// Typed client for the local API (contracts/api.md). US1 covers list + create;
// later stories extend this file.

export interface Bookmark {
  id: number;
  url: string;
  title: string;
  description: string;
  tags: string[];
  createdAt: string;
  updatedAt: string;
}

export interface ApiErrorBody {
  error: string;
  message: string;
  existing?: Bookmark;
}

export class ApiError extends Error {
  constructor(
    readonly status: number,
    readonly body: ApiErrorBody,
  ) {
    super(body.message);
  }
}

async function parse<T>(res: Response): Promise<T> {
  const data = await res.json();
  if (!res.ok) throw new ApiError(res.status, data as ApiErrorBody);
  return data as T;
}

export async function listBookmarks(
  sort: 'created_desc' | 'created_asc' | 'title_asc' = 'created_desc',
): Promise<Bookmark[]> {
  const res = await fetch(`/api/bookmarks?sort=${sort}`);
  const data = await parse<{ bookmarks: Bookmark[] }>(res);
  return data.bookmarks;
}

export interface NewBookmark {
  url: string;
  title?: string;
  description?: string;
  tags?: string[];
}

export async function createBookmark(input: NewBookmark): Promise<Bookmark> {
  const res = await fetch('/api/bookmarks', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(input),
  });
  return parse<Bookmark>(res);
}

