import { useEffect, useState } from 'react';
import { listBookmarks, type Bookmark } from './api';
import { AddBookmarkForm } from './components/AddBookmarkForm';
import { BookmarkList } from './components/BookmarkList';
import { SearchBar } from './components/SearchBar';

export function App() {
  const [bookmarks, setBookmarks] = useState<Bookmark[]>([]);
  const [query, setQuery] = useState('');
  const [loading, setLoading] = useState(true);

  // Fetch (and re-fetch on search) from the server, debounced so typing doesn't
  // fire a request per keystroke.
  useEffect(() => {
    const handle = setTimeout(() => {
      listBookmarks({ q: query })
        .then(setBookmarks)
        .finally(() => setLoading(false));
    }, 150);
    return () => clearTimeout(handle);
  }, [query]);

  return (
    <main className="app">
      <h1>Bookmark Manager</h1>
      <AddBookmarkForm onAdded={(b) => setBookmarks((prev) => [b, ...prev])} />
      <SearchBar value={query} onChange={setQuery} />
      {loading ? (
        <p>Loading…</p>
      ) : (
        <BookmarkList bookmarks={bookmarks} query={query} />
      )}
    </main>
  );
}

