            title="Rename tag"
            onClick={() => onRename(t)}
          >
            ✎
          </button>
          <button
            type="button"
            className="mini"
            title="Remove tag"
            onClick={() => onRemove(t)}
          >
            ×
          </button>
        </span>
      ))}
    </div>
  );
}

