async function byTag(tag: string) {
  const res = await app.inject({
    method: 'GET',
    url: `/api/bookmarks?tag=${encodeURIComponent(tag)}`,
  });
  return (res.json().bookmarks as { title: string }[]).map((b) => b.title);
