// Applies a partial update. US3 uses this to replace a bookmark's tag set;
// US4 extends it to title/url/description. Bumps updated_at when anything
// changes (FR-009, FR-011).
export function updateBookmark(
  db: DB,
  id: number,
  input: UpdateInput,
  deps: Deps = defaultDeps,
): Bookmark {
  const exists = db
    .prepare(`SELECT id FROM bookmarks WHERE id = ? AND deleted_at IS NULL`)
    .get(id) as { id: number } | undefined;
  if (!exists) throw notFound();

  const tx = db.transaction(() => {
    if (input.tags) {
      db.prepare(`DELETE FROM bookmark_tags WHERE bookmark_id = ?`).run(id);
      attachTags(db, id, input.tags);
    }
    db.prepare(`UPDATE bookmarks SET updated_at = ? WHERE id = ?`).run(
      deps.now(),
      id,
    );
  });
  tx();

  return getBookmark(db, id)!;
}

